import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        FastScanner in = new FastScanner(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().run(in, out);
        out.close();
    }

    static class Solver {
        void run(FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            if (n > 11) {
                out.println("0");
                return;
            }
            Point[] pts = new Point[n];
            for (int i = 0; i < n; i++) {
                pts[i] = new Point(in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt(), in.nextInt());
            }
            List<Integer> good = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                final int fi = i;
                boolean bad = IntStream.range(0, n).anyMatch(j ->
                        IntStream.range(0, n).anyMatch(k -> {
                            if (fi != j && fi != k && j != k) {
                                Point v1 = pts[j].sub(pts[fi]);
                                Point v2 = pts[k].sub(pts[fi]);
                                return acute(v1, v2);
                            }
                            return false;
                        })
                );
                if (!bad) good.add(i + 1);
            }
            if (good.isEmpty()) {
                out.println("0");
            } else {
                out.println(good.size());
                good.forEach(out::println);
            }
        }

        static boolean acute(Point a, Point b) {
            double dot = a.a*b.a + a.b*b.b + a.c*b.c + a.d*b.d + a.e*b.e;
            double ang = Math.acos(dot / (a.mag() * b.mag()));
            return Math.toDegrees(ang) < 90;
        }
    }

    static class Point {
        int a, b, c, d, e;
        Point(int a, int b, int c, int d, int e) {
            this.a = a; this.b = b; this.c = c; this.d = d; this.e = e;
        }
        Point sub(Point o) {
            return new Point(a-o.a, b-o.b, c-o.c, d-o.d, e-o.e);
        }
        double mag() {
            return Math.sqrt(a*a + b*b + c*c + d*d + e*e);
        }
    }

    static class FastScanner {
        BufferedReader reader;
        StringTokenizer tokenizer;
        FastScanner(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }
        String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }
        int nextInt() { return Integer.parseInt(next()); }
    }
}
